window.REPORT_PRELOAD_CACHE["TAK.html"] = {"version":"ec780480d4ba9774553ea03a9b3be86a79ad248fdbaf0dfa5d9cd5f0e59d37c6","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>武田制药 Takeda Pharmaceutical (NYSE: TAK / TSE: 4502) 深度研究报告：从跨国并购消化期到创新管线收获与盈利修复复利引擎</title>\n    <!-- Tailwind CSS -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <!-- Chart.js -->\n    <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n    <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n    <script>\n    tailwind.config = {\n        darkMode: 'class',\n        theme: {\n            extend: {\n                fontFamily: {\n                    sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n                    mono: ['JetBrains Mono', 'monospace'],\n                },\n                colors: {\n                    navy: {\n                        950: '#070B14',\n                        900: '#0F172A',\n                        800: '#1E293B',\n                        700: '#334155',\n                    },\n                    takedared: {\n                        400: '#FF6B6B',\n                        500: '#D50032',\n                        600: '#B2002A',\n                    },\n                    accent: {\n                        500: '#3B82F6',\n                        600: '#2563EB',\n                    },\n                    teal: {\n                        500: '#06B6D4',\n                        600: '#0891B2',\n                    }\n                }\n            }\n        }\n    }\n    </script>\n\n    <style>\n    ::-webkit-scrollbar {\n        width: 6px;\n        height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n        background: transparent;\n    }\n    ::-webkit-scrollbar-thumb {\n        background: #94A3B8;\n        border-radius: 3px;\n    }\n    .dark ::-webkit-scrollbar-thumb {\n        background: #475569;\n    }\n\n    @media print {\n        #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n            display: none !important;\n        }\n        main {\n            margin-left: 0 !important;\n            padding: 0 !important;\n        }\n        section {\n            break-inside: avoid;\n        }\n    }\n\n    .report-card {\n        transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n    }\n    .report-card:hover {\n        transform: translateY(-2px);\n    }\n\n    .nav-link.active {\n        background: linear-gradient(90deg, rgba(213, 0, 50, 0.22) 0%, rgba(6, 182, 212, 0.06) 100%);\n        border-left: 3px solid #D50032;\n        color: #FFFFFF;\n        font-weight: 600;\n    }\n    </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-takedared-500 selection:text-white transition-colors duration-200\">\n\n    <!-- 顶部全局阅读进度条 -->\n    <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n        <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-takedared-500 via-amber-400 to-teal-500 w-0 transition-all duration-150\"></div>\n    </div>\n\n    <!-- 移动端顶部导航栏 -->\n    <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n        <div class=\"flex items-center space-x-2.5\">\n            <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-takedared-500 to-takedared-600 flex items-center justify-center font-extrabold text-white shadow\">\n                TK\n            </div>\n            <div>\n                <div class=\"text-[11px] text-takedared-400 font-semibold tracking-wider uppercase\">NYSE: TAK / TSE: 4502 · Equity Research</div>\n                <div class=\"text-sm font-bold leading-tight\">武田制药 Takeda 深度研究报告</div>\n            </div>\n        </div>\n        <div class=\"flex items-center space-x-2\">\n            <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n                <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n                <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n            </button>\n            <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n                <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n            </button>\n        </div>\n    </header>\n\n    <!-- 移动端折叠抽屉菜单 -->\n    <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n        <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n        <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n            <div>\n                <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n                    <span class=\"font-bold text-white text-base\">TAK 研报目录导航</span>\n                    <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n                        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n                    </button>\n                </div>\n                <ul class=\"mt-4 space-y-1.5 text-sm\">\n                    <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n                    <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构</a></li>\n                    <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n                    <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n                    <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与估值体系</a></li>\n                    <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n                    <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n                </ul>\n            </div>\n            <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n                <p>全球生物制药与跨国药企研究组</p>\n                <p class=\"mt-1\">数据基准：2026财年H1 (截至2026年9月30日)</p>\n            </div>\n        </nav>\n    </div>\n\n    <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n    <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n        <div>\n            <!-- 机构品牌头 -->\n            <div class=\"p-5 border-b border-slate-800/80\">\n                <div class=\"flex items-center space-x-3\">\n                    <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-takedared-500 to-takedared-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-takedared-500/25\">\n                        TAK\n                    </div>\n                    <div>\n                        <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-takedared-400 bg-takedared-500/15 px-2 py-0.5 rounded\">NYSE: TAK / TSE: 4502</span>\n                        <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">武田制药深度研报</h2>\n                    </div>\n                </div>\n                <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n                    全球跨国制药巨头 · 消化期后创新管线收获与强劲盈利修复引擎\n                </p>\n            </div>\n\n            <!-- 股票实时快照徽章 -->\n            <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n                <div class=\"flex items-center justify-between\">\n                    <span class=\"text-slate-400\">FY2026 H1 营收</span>\n                    <span class=\"font-mono font-bold text-white\">¥2,407.0B <span class=\"text-takedared-400\">(+8.4% YoY)</span></span>\n                </div>\n                <div class=\"flex items-center justify-between\">\n                    <span class=\"text-slate-400\">FY2026 H1 经营利润</span>\n                    <span class=\"font-mono font-bold text-teal-400\">¥406.7B <span class=\"text-slate-400\">(+60.4%)</span></span>\n                </div>\n                <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n                    <span class=\"text-slate-400\">股息率 (Dividend Yield)</span>\n                    <span class=\"font-mono font-bold text-takedared-400\">~2.44% (35年连续派息)</span>\n                </div>\n            </div>\n\n            <!-- 六个核心章节目录导航 -->\n            <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n                <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n                <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n                    <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-takedared-400 mr-2\">00</span>执行摘要与核心指标</span>\n                    </a>\n                    <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与收入架构</span>\n                    </a>\n                    <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n                    </a>\n                    <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局横向对比</span>\n                    </a>\n                    <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值体系</span>\n                    </a>\n                    <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n                    </a>\n                    <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n                    </a>\n                </nav>\n            </div>\n        </div>\n\n        <!-- 侧边栏底部工具栏 -->\n        <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n            <div class=\"flex items-center justify-between\">\n                <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n                <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n                    <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n                    <svg class=\"w-3.5 h-3.5 text-takedared-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n                    <span class=\"dark:hidden\">深色护眼模式</span>\n                    <span class=\"hidden dark:inline\">机构亮色模式</span>\n                </button>\n            </div>\n            <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-takedared-500 hover:bg-takedared-600 text-white text-xs font-extrabold transition shadow-sm\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n                <span>打印 / 导出 PDF 研报</span>\n            </button>\n        </div>\n    </aside>\n\n    <!-- 主内容区 -->\n    <main class=\"lg:ml-[280px] min-h-screen\">\n        <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n            <!-- =========================================================\n            00. Hero 研报封面区与执行摘要\n            ========================================================= -->\n            <section id=\"sec-exec\" class=\"scroll-mt-20\">\n                <!-- 顶部研报元数据标签栏 -->\n                <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n                    <div class=\"flex flex-wrap items-center gap-2\">\n                        <span class=\"px-2.5 py-1 rounded-md bg-takedared-500/15 text-takedared-600 dark:text-takedared-400 font-bold border border-takedared-500/30\">评级：强烈买入 / 创新管线收获期高息防御标的</span>\n                        <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：FY2026–2030 创新药密集上市与重磅管线兑现期</span>\n                    </div>\n                    <div class=\"flex items-center space-x-3 font-mono\">\n                        <span>覆盖时间：2026年11月</span>\n                        <span>NYSE: TAK / TSE: 4502</span>\n                    </div>\n                </div>\n\n                <!-- Hero 标题卡片 -->\n                <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n                    <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#D50032 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n                    <div class=\"relative z-10\">\n                        <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-takedared-500/20 border border-takedared-500/40 text-takedared-400 text-xs font-semibold mb-4\">\n                            <span class=\"w-2 h-2 rounded-full bg-takedared-400 animate-pulse\"></span>\n                            <span>CORE THESIS · 2021-2025 管线深厚积淀释放 × FY26 H1 经营利润大增 +60.4% 与重磅新药全球放量</span>\n                        </div>\n                        <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n                            武田制药 Takeda Pharmaceutical Company Limited (NYSE: TAK / TSE: 4502) 深度研究报告：从跨国并购消化期到创新管线收获与盈利修复复利引擎\n                        </h1>\n                        <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n                            武田制药作为总部位于东京、业务遍及全球 80 多个国家的全球 Top 20 生物制药巨头，在成功消化 Shire 并购后的阵痛期后，迎来重磅业绩与管线双拐点。FY2026 上半年（截至2026年9月30日）实现营收 <strong class=\"text-takedared-400\">¥2,407.0B (+8.4% YoY)</strong>，经营利润飙升 <strong class=\"text-white\">+60.4%</strong> 达 ¥406.7B，净利润暴增 <strong class=\"text-teal-400\">+171.8%</strong>。\n                            随着 8 款具备数十亿美元潜力的后期创新管线在 2026–2030+ 阶段密集商业化（如近期获批上市的 ORZEYFUL、MIMRYLO 及 III 期临床大获成功的 TAK-921），公司正展现出极强的现金创造力与估值修复空间。\n                        </p>\n\n                        <!-- 核心投资结论高亮条 -->\n                        <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">FY26 H1 业绩远超预期</div>\n                                <div class=\"text-white font-semibold\">营业利润达 ¥406.7B (+60.4% YoY)，经营利润率大幅提升 5.5 个百分点至 16.9%</div>\n                            </div>\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">创新管线 Kaizen 收获期</div>\n                                <div class=\"text-takedared-400 font-semibold\">8 款数十亿美元级后期重磅管线蓄势待发，ORZEYFUL、MIMRYLO 等全球陆续放量</div>\n                            </div>\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">股东回报与高分红韧性</div>\n                                <div class=\"text-teal-400 font-semibold\">维持 35 年连续稳定派息（股息率 ~2.44%），叠加庞大自由现金流，兼具防御与成长</div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 4个核心 KPI 卡片 -->\n                <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n                    <!-- KPI 1 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>FY2026 H1 营业收入</span>\n                            <span class=\"p-1.5 rounded-lg bg-takedared-500/15 text-takedared-600 dark:text-takedared-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">¥2,407.0B</span>\n                            <span class=\"text-xs font-bold text-takedared-600 dark:text-takedared-400 bg-takedared-500/15 px-2 py-0.5 rounded\">+8.4% YoY</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            新产品放量增长（+17.3%）与汇率利好共同驱动上半年营收稳健走高。\n                        </p>\n                    </div>\n\n                    <!-- KPI 2 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>FY2026 H1 经营利润</span>\n                            <span class=\"p-1.5 rounded-lg bg-accent-500/10 text-accent-600 dark:text-accent-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M5 12h14M5 12a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v4a2 2 0 01-2 2M5 12a2 2 0 00-2 2v4a2 2 0 002 2h14a2 2 0 002-2v-4a2 2 0 00-2-2m-2-4h.01M17 16h.01\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">¥406.7B</span>\n                            <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400 bg-accent-500/10 px-2 py-0.5 rounded\">+60.4% YoY</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            严格的成本管控与转型降本带来显著利润弹性，经营利润率大幅扩张 5.5 个百分点至 16.9%。\n                        </p>\n                    </div>\n\n                    <!-- KPI 3 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>全年上修指引 (Core Operating Profit)</span>\n                            <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">¥1,190.0B</span>\n                            <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">上修全年预期</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            受益于强劲业绩与汇率利好，公司上调 FY2026 全年核心经营利润及 Core EPS 预期。\n                        </p>\n                    </div>\n\n                    <!-- KPI 4 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>美国 ADR 股价与估值</span>\n                            <span class=\"p-1.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$21.43</span>\n                            <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">分析师一致强推</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            华尔街分析师平均评级为“强烈买入”，目标价空间显著，兼具创新药爆发与高股息防守。\n                        </p>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            一、 业务与收入架构 (Business & Revenue Architecture)\n            ========================================================= -->\n            <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-takedared-600 dark:text-takedared-400\">Section 01 · Business & Revenue Architecture</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：五大核心治疗领域与全球多元化布局</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY2026 H1 总营收 ¥2,407.0B · 美国市场贡献核心份额</span>\n                </div>\n\n                <!-- 交互式 Chart.js 双视图切换面板 -->\n                <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n                    <!-- 左侧：双视图图表 -->\n                    <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n                            <div>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">FY2023–FY2027E 核心营业收入与利润演进趋势</h3>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">FY26 上半年营收实现 +8.4% 增长，经营利润强劲跃升至 ¥406.7B</p>\n                            </div>\n                            <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n                                <button onclick=\"switchBizChart('revenue')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-takedared-600 dark:text-takedared-400 shadow-sm transition\">视图A：营收与利润演进</button>\n                                <button onclick=\"switchBizChart('areas')\" id=\"btn-chart-are\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">视图B：五大核心治疗领域</button>\n                            </div>\n                        </div>\n                        <div class=\"relative h-72 w-full\">\n                            <canvas id=\"bizArchitectureChart\"></canvas>\n                        </div>\n                    </div>\n\n                    <!-- 右侧：结构性拆解核心洞察 -->\n                    <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业架构三大结构性拐点</h3>\n                            <ul class=\"space-y-4 text-sm\">\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-takedared-500/15 text-takedared-600 dark:text-takedared-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">消化系统与罕见病双核驱动</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            核心产品如 ENTYVIO（维得利珠单抗，溃疡性结肠炎/克罗恩病重磅炸弹）持续稳健放量，即便面对部分专利到期产品（如 VYVANSE）的冲击，新老产品交替依然顺利。\n                                        </p>\n                                    </div>\n                                </li>\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">新产品密集上市（ORZEYFUL & MIMRYLO）</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            近期在全球和中、美市场密集上市的新药（如 ORZEYFUL、MIMRYLO）成为收入增长的新引擎，新产品群整体增速达 +17.3%。\n                                        </p>\n                                    </div>\n                                </li>\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">全球化布局与美国市场核心地位</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            作为总部位于日本的药企，其超过一半以上的营收来自于美国市场，同时深度覆盖欧洲、中国及新兴市场，实现全球化抗风险布局。\n                                        </p>\n                                    </div>\n                                </li>\n                            </ul>\n                        </div>\n                        <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n                            <span class=\"text-slate-500 dark:text-slate-400\">核心业务支柱</span>\n                            <span class=\"font-bold text-takedared-600 dark:text-takedared-400\">消化、罕见病、神经科学、肿瘤与血液制品</span>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 五大核心治疗领域矩阵卡片 -->\n                <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-takedared-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-3\">\n                                <span class=\"px-2.5 py-1 rounded-md bg-takedared-500/15 text-takedared-600 dark:text-takedared-400 text-xs font-bold\">核心支柱 · 消化健康</span>\n                                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">ENTYVIO 领衔</span>\n                            </div>\n                            <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">1. 消化系统疾病 (Gastroenterology)</h3>\n                            <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                旗舰产品 ENTYVIO 持续扩展适应症与剂型（Treat-To-Target 临床试验表明可将并发症风险降低近 70%），稳居全球炎症性肠病治疗绝对龙头。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n                            IBD 治疗全球金标准 · 专利护城河深厚\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-3\">\n                                <span class=\"px-2.5 py-1 rounded-md bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">高增长 · 罕见病</span>\n                                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">高壁垒高黏性</span>\n                            </div>\n                            <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">2. 罕见病 (Rare Diseases)</h3>\n                            <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                继承自 Shire 并购的优质罕见病资产组合，涵盖罕见血液病、遗传代谢病等，具备极高的临床壁垒与长期稳定的现金流回报。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold\">\n                            Shire 整合红利 · 专科壁垒高\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-3\">\n                                <span class=\"px-2.5 py-1 rounded-md bg-accent-500/10 text-accent-600 dark:text-accent-400 text-xs font-bold\">专科领域 · 神经科学</span>\n                                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">中枢神经创新</span>\n                            </div>\n                            <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">3. 神经科学 (Neuroscience)</h3>\n                            <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                专注精神医学与神经退行性疾病，尽管面临 VYVANSE 专利到期挑战，正通过新一代中枢神经创新管线平稳过渡。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold\">\n                            精神与神经专科 · 持续迭代\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-indigo-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-3\">\n                                <span class=\"px-2.5 py-1 rounded-md bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">尖端阵地 · 肿瘤学</span>\n                                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">精准靶向与ADC</span>\n                            </div>\n                            <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">4. 肿瘤学 (Oncology)</h3>\n                            <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                聚焦血液瘤与实体瘤靶向疗法，近期重磅进展如靶向 Claudin 18.2 的抗体偶联药物（ADC）TAK-921 在晚期胃癌 III 期临床中显示出优异的生存期获益。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold\">\n                            TAK-921 (胃癌ADC) III期大捷\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-amber-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-3\">\n                                <span class=\"px-2.5 py-1 rounded-md bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">基石业务 · 血液制品</span>\n                                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">全球血浆采集网</span>\n                            </div>\n                            <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">5. 血浆衍生疗法 (Plasma-Derived Therapies)</h3>\n                            <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                全球领先的血浆采集与血液制品生产网络，为免疫缺陷和罕见急重症患者提供不可或缺的生命支持疗法。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold\">\n                            刚需生命线 · 全球稳定供应\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-slate-400 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-3\">\n                                <span class=\"px-2.5 py-1 rounded-md bg-slate-500/10 text-slate-600 dark:text-slate-400 text-xs font-bold\">管线爆发 · 2026-2030</span>\n                                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">8大重磅新药</span>\n                            </div>\n                            <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">6. 创新管线 Kaizen 计划</h3>\n                            <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                经过 2021-2025 年研发管线精简与聚焦，目前手握 8 款具备数十亿美元销售潜力的后期创新药，进入密集收获期。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n                            研发总监评价：“现代史上最佳管线”\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            二、 行业地位与四重核心护城河 (Industry Position & Moat)\n            ======================================================== -->\n            <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Industry Position & Economic Moat</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：专科壁垒、全球商业化与研发管线</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Moat · 全球生物制药创新领跑者)</span>\n                </div>\n\n                <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n                    <!-- 左侧：四重护城河深度解析 -->\n                    <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-takedared-500/15 text-takedared-600 dark:text-takedared-400 flex items-center justify-center font-bold text-sm\">01</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">专科与罕见病领域的深厚临床壁垒</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                消化系统与罕见病治疗具备极高的医生心智、临床数据积累和长周期患者黏性，新进入者极难在短期内复制其临床试验与真实世界证据优势。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-accent-500/15 text-accent-600 dark:text-accent-400 flex items-center justify-center font-bold text-sm\">02</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">覆盖 80 国的全球化商业化与准入网络</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                拥有横跨美国、欧洲、日本及新兴市场的强大药品准入和合规分销团队，能够将研发成功的创新药在最短时间内推向全球主要医药市场。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">8 大数十亿美元级后期创新管线储备</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                经过近年战略聚焦与研发管线 Kaizen 优化，手握 8 款具备重磅炸弹潜力的后期资产，确保在专利悬崖周期中实现平稳且高质的增长接力。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">严苛的成本管理与转型降本纪律</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                持续推进组织变革与数字化转型，已实现数百亿日元的年度经营成本节约（Transformation Savings），大幅释放 P&L 利润空间。\n                            </p>\n                        </div>\n                    </div>\n\n                    <!-- 右侧：五维护城河雷达图 -->\n                    <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">生物制药行业五维护城河量化雷达图</h3>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">武田制药 (TAK) vs 大型跨国药企平均 vs 仿制药/专科药企（满分 10 分）</p>\n                        <div class=\"relative h-72 w-full\">\n                            <canvas id=\"moatRadarChart\"></canvas>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            三、 同行竞争格局横向对比 (Competitive Landscape)\n            ========================================================= -->\n            <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-takedared-600 dark:text-takedared-400\">Section 03 · Global Competitive Landscape</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 同行竞争格局横向对比：全球大药企与专科制药强者</h2>\n                    </div>\n                    <!-- 交互式筛选按钮 -->\n                    <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n                        <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-takedared-500 text-white shadow-sm transition\">全部阵营</button>\n                        <button onclick=\"filterCompetitors('globalpharma')\" data-filter=\"globalpharma\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">跨国综合制药巨头</button>\n                        <button onclick=\"filterCompetitors('specialty')\" data-filter=\"specialty\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">专科与罕见病领跑者</button>\n                    </div>\n                </div>\n\n                <!-- 横向对比矩阵表格 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n                    <div class=\"overflow-x-auto\">\n                        <table class=\"w-full text-left border-collapse\">\n                            <thead>\n                                <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n                                    <th class=\"py-4 px-5 min-w-[180px]\">竞争厂商与核心代表</th>\n                                    <th class=\"py-4 px-4 min-w-[130px]\">核心治疗领域</th>\n                                    <th class=\"py-4 px-4 min-w-[140px]\">估值与股息特征</th>\n                                    <th class=\"py-4 px-4 min-w-[135px]\">毛利率水平</th>\n                                    <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与竞争评估</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n                                <tr data-category=\"globalpharma\" class=\"bg-takedared-500/5 dark:bg-takedared-500/10 font-medium\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"flex items-center space-x-2\">\n                                            <span class=\"px-2 py-0.5 rounded bg-takedared-500 text-white text-[10px] font-extrabold\">跨国巨头</span>\n                                            <span class=\"font-bold text-slate-900 dark:text-white\">武田制药 Takeda (TAK)</span>\n                                        </div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">消化、罕见病、神经科学、肿瘤</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">专科处方药与血液制品</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-900 dark:text-white\">股息率 ~2.44% (35年连派)</td>\n                                    <td class=\"py-4 px-4 font-mono font-bold text-takedared-600 dark:text-takedared-400\">~64.8% (高毛利)</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>盈利修复与管线井喷：</strong>FY26 H1 经营利润大增 +60.4%，8大后期重磅管线开启长期成长通道。\n                                    </td>\n                                </tr>\n\n                                <tr data-category=\"globalpharma\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">艾伯维 AbbVie (ABBV)</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">全球免疫学与肉毒素巨头</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">免疫学、肿瘤、神经科学、医美</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">较高 P/E · 稳健高分红</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~68% - 72%</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>超级重磅炸弹支撑：</strong>Skyrizi 与 Rinvoq 成功接棒 Humira，整体规模与市值领先，但估值也相对较高。\n                                    </td>\n                                </tr>\n\n                                <tr data-category=\"specialty\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">CSL Limited (CSL)</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">全球血浆制品与疫苗双雄</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">血浆衍生疗法、流感疫苗</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">成长型专科估值</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~55% - 60%</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>血浆龙头标杆：</strong>在血浆采集和特定血液蛋白领域具备极强规模效应，与武田血浆业务形成直接对标。\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n\n                <!-- 配套 Chart.js 横向条形图：毛利率与盈利对比 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球主要生物制药厂商毛利率（Gross Profit Margin）对比</h3>\n                            <p class=\"text-xs text-slate-500 dark:text-slate-400\">武田制药毛利率保持在 ~64.8% 的健康高位，体现专科处方药与血浆制品的强大定价权</p>\n                        </div>\n                        <span class=\"text-xs font-semibold text-takedared-600 dark:text-takedared-400 bg-takedared-500/15 px-2.5 py-1 rounded\">专科创新药带来优异盈利基底</span>\n                    </div>\n                    <div class=\"relative h-60 w-full\">\n                        <canvas id=\"compMarginChart\"></canvas>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            四、 财务健康度与估值体系解析 (Financial Health & Valuation)\n            ========================================================= -->\n            <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation Framework</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康与估值体系：经营利润暴增 +60.4% 与高分红防御</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">调整后自由现金流 ¥325.7B (H1) · 股息率 ~2.44%</span>\n                </div>\n\n                <!-- 1. 财务健康度四大硬核指标卡 -->\n                <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-takedared-600 dark:text-takedared-400 uppercase\">Gross Profit Margin</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~64.8%</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            高壁垒专科药与生物制品组合推动毛利率长期稳居 65% 左右的健康区间。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Operating Profit (H1)</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">¥406.7B</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            2026 财年上半年经营利润同比大增 +60.4%，经营利润率大幅提升至 16.9%。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Free Cash Flow (H1)</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">¥325.7B</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            调整后自由现金流在上半年达到 ¥3,257 亿日元，全年指引更进一步上修至 7,000–8,000 亿日元。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-accent-600 dark:text-accent-400 uppercase\">Dividend Yield</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~2.44%</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            已连续 35 年保持稳定派息记录，现金流收益率达 7%，具备极强的长期分红防御属性。\n                        </p>\n                    </div>\n                </div>\n\n                <!-- 2. 交互式 Chart.js 财务演进双轴图 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">FY2023–FY2027E 营收与经营利润爆发复苏趋势</h3>\n                            <p class=\"text-xs text-slate-500 dark:text-slate-400\">并购消化期平稳度过：FY26 营收向 ¥4.70T 迈进，经营利润与现金流弹性全面释放</p>\n                        </div>\n                        <span class=\"text-xs font-mono font-bold text-takedared-600 dark:text-takedared-400 bg-takedared-500/10 px-2.5 py-1 rounded\">FY26 Core Operating Profit ¥1.19T</span>\n                    </div>\n                    <div class=\"relative h-72 w-full\">\n                        <canvas id=\"valEvolutionChart\"></canvas>\n                    </div>\n                </div>\n\n                <!-- 3. 互动式复利推演计算器 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 sm:p-8 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col md:flex-row justify-between md:items-center gap-4 mb-6\">\n                        <div>\n                            <h3 class=\"text-lg font-bold text-white\">武田制药 (TAK) 投资回报与复利推演器</h3>\n                            <p class=\"text-xs text-slate-400 mt-1\">模拟在不同营收增速与创新药放量预期下的长期持仓市值与复合回报率</p>\n                        </div>\n                        <span class=\"text-xs px-3 py-1 rounded-full bg-slate-800 text-takedared-300 border border-slate-700\">交互式推演模型</span>\n                    </div>\n\n                    <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-8 items-center\">\n                        <div class=\"space-y-5\">\n                            <div>\n                                <div class=\"flex justify-between text-sm mb-1\">\n                                    <span class=\"text-slate-300\">初始投资本金 (USD)</span>\n                                    <span id=\"invVal\" class=\"font-bold text-white\">$20,000</span>\n                                </div>\n                                <input id=\"invSlider\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"20000\" class=\"w-full accent-takedared-400 cursor-pointer\">\n                            </div>\n                            <div>\n                                <div class=\"flex justify-between text-sm mb-1\">\n                                    <span class=\"text-slate-300\">持有年限 (Years)</span>\n                                    <span id=\"yrVal\" class=\"font-bold text-white\">3 年</span>\n                                </div>\n                                <input id=\"yrSlider\" type=\"range\" min=\"1\" max=\"10\" step=\"1\" value=\"3\" class=\"w-full accent-takedared-400 cursor-pointer\">\n                            </div>\n                            <div>\n                                <div class=\"flex justify-between text-sm mb-1\">\n                                    <span class=\"text-slate-300\">预期年化营收/盈利增速</span>\n                                    <span id=\"grVal\" class=\"font-bold text-takedared-400\">7.0%</span>\n                                </div>\n                                <input id=\"grSlider\" type=\"range\" min=\"2\" max=\"18\" step=\"0.5\" value=\"7.0\" class=\"w-full accent-takedared-400 cursor-pointer\">\n                            </div>\n                        </div>\n\n                        <div class=\"lg:col-span-2 grid grid-cols-1 sm:grid-cols-3 gap-4\">\n                            <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n                                <div class=\"text-xs text-slate-400\">期末预计总资产市值</div>\n                                <div id=\"finalBalance\" class=\"text-2xl font-bold text-white mt-2\">$24,500</div>\n                                <div id=\"totalGainPct\" class=\"text-xs text-takedared-400 mt-1\">累计总回报 +22.5%</div>\n                            </div>\n                            <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n                                <div class=\"text-xs text-slate-400\">期末对应隐含股价 (ADR)</div>\n                                <div id=\"impliedPrice\" class=\"text-2xl font-bold text-teal-400 mt-2\">$26.20</div>\n                                <div class=\"text-xs text-slate-400 mt-1\">基于利润兑现与估值修复</div>\n                            </div>\n                            <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n                                <div class=\"text-xs text-slate-400\">隐含复合年化回报 (CAGR)</div>\n                                <div id=\"cagrVal\" class=\"text-2xl font-bold text-amber-400 mt-2\">7.0%</div>\n                                <div class=\"text-xs text-slate-400 mt-1\">稳定成长加 2.4% 股息收益</div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            五、 投资决策与风险配置框架 (Investment Decision & Risk)\n            ========================================================= -->\n            <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-takedared-600 dark:text-takedared-400\">Section 05 · Investment Decision & Risk Allocation</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景推演与核心风险</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：医疗健康组合中的高分红防御与创新药成长标的</span>\n                </div>\n\n                <!-- 1. 三情景估值推演卡片 -->\n                <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-takedared-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-takedared-500/15 text-takedared-600 dark:text-takedared-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-takedared-600 dark:text-takedared-400\">概率：30%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标价格：$28.00+</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>8 款后期重磅管线商业化进展超越华尔街预期，TAK-921 等 ADC 药物加速获批，新产品销售爆发带动核心 EPS 持续超预期。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-takedared-600 dark:text-takedared-400\">\n                            潜在上行空间：+30% 至 +45%\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-accent-500/15 text-accent-600 dark:text-accent-400 text-xs font-bold\">基准情景 (Base Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-accent-600 dark:text-accent-400\">概率：50%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标价格：$23.00 – $25.00</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>FY26 上半年强劲势头全年顺利兑现，Core Operating Profit 稳健达成 ¥1.19T 指引，维持稳定高分红回报。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-accent-600 dark:text-accent-400\">\n                            潜在上行空间：+10% 至 +20%\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">防御价格：$18.00 – $19.50</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>部分成熟产品及专利到期产品（LoE）下滑超预期，研发管线临床试验遭遇阶段性挫折，汇率产生大幅逆风。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n                            潜在下行回撤：-10% 至 -15% (高股息筑底)\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 2. 四大核心风险评估矩阵 -->\n                <div>\n                    <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心风险评估与机构应对策略</h3>\n                    <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 成熟产品专利到期（LoE）冲击</span>\n                                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">VYVANSE 等核心老药专利悬崖</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                部分成熟产品面临仿制药或生物类似药的持续侵蚀，若新产品放量速度未能完全对冲老药下滑，将对短期营收增速产生掣肘。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 汇率剧烈波动风险（日元兑美元）</span>\n                                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">跨国财报折算与汇兑损益</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                作为总部在日本、主要营收在美国及全球的跨国药企，日元汇率的剧烈双向波动会对以日元计价的财务报表及 ADR 表现带来阶段性干扰。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · 临床试验与监管审批风险</span>\n                                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">创新管线临床与 FDA 审批不确定性</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                创新药研发高度依赖临床试验结果与各国药监局（如 FDA、PMDA）的审评尺度，管线推进若遇延期将影响中长期增长预期。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 药品价格压制与医保政策收紧</span>\n                                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">全球药价谈判与控费压力</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                美国 IRA（通胀削减法案）药价谈判及欧洲各国的药品报销价格压制，对全球跨国药企的单品定价和毛利空间提出持续挑战。\n                            </p>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n            ========================================================= -->\n            <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n                    </div>\n                    <div class=\"flex items-center space-x-2 no-print\">\n                        <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-takedared-500/15 text-takedared-600 dark:text-takedared-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n                        <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n                    </div>\n                </div>\n\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n                        点击勾选机构财报追踪已验证达标的核心指标（状态自动本地保存），用高频基本面事实动态校准投资逻辑：\n                    </p>\n\n                    <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n                        <!-- KPI 1 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#D50032] focus:ring-takedared-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 全年核心经营利润（Core Operating Profit）达成率</span>\n                                    <span class=\"text-[11px] font-mono text-takedared-600 dark:text-takedared-400 font-semibold shrink-0\">盈利指引锚点</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    监控 FY2026 全年修订后的 ¥1.19T 核心经营利润目标的落实情况与降本增效成果。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 2 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#D50032] focus:ring-takedared-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 新产品放量速度（如 ORZEYFUL、MIMRYLO 商业化）</span>\n                                    <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">新药放量指标</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    追踪新获批上市药物在全球各大主要市场的销售额爬坡曲线，确保新产品群保持两位数高增。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 3 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#D50032] focus:ring-takedared-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. ENTYVIO 旗舰产品及核心支柱品牌的市场稳固度</span>\n                                    <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold shrink-0\">核心现金流保卫</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    评估 ENTYVIO 在全球炎症性肠病市场的份额及皮下注射/静脉新剂型的渗透率。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 4 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#D50032] focus:ring-takedared-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 调整后自由现金流（Adjusted FCF）达成情况（目标 ¥700B–800B）</span>\n                                    <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">现金流造血能力</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    监控全年自由现金流指引的上修兑现情况，保障高分红政策的资金安全边际。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 5 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#D50032] focus:ring-takedared-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 8大后期创新管线（如 TAK-921、zasocitinib）监管与临床催化剂</span>\n                                    <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">管线价值重估</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    跟踪关键管线（如胃癌 ADC 药物 TAK-921、银屑病新药 zasocitinib 等）的 FDA 审批与注册临床进展。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 6 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#D50032] focus:ring-takedared-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 转型节省（Transformation Savings）与重组成本优化进度</span>\n                                    <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">组织降本增效</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    评估每年数百亿日元经营成本节约的兑现度及重组费用是否控制在预算范围内。\n                                </p>\n                            </div>\n                        </label>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            页脚免责声明 (Disclaimer Footer)\n            ========================================================= -->\n            <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n                <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n                    <span>武田制药 Takeda Pharmaceutical (NYSE: TAK / TSE: 4502) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n                    <span>数据基准：FY2026 上半年财报及 2026 年 11 月最新市场行情</span>\n                </div>\n                <p class=\"leading-relaxed\">\n                    <strong>免责声明：</strong>本深度研究报告基于公司公开财务报告、SEC 6-K 文件及市场公开一致预期数据整理生成，旨在提供结构化的产业分析与机构估值研究框架。报告中涉及的财务预测、三情景估值模型及推演数据均基于特定产业假设，不构成任何具体的证券买卖建议、要约或投资承诺。投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n                </p>\n            </footer>\n\n        </div>\n    </main>\n\n    <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n    <script>\n    function toggleTheme() {\n        const html = document.documentElement;\n        html.classList.toggle('dark');\n        updateChartsTheme();\n    }\n\n    function toggleMobileMenu() {\n        const drawer = document.getElementById('mobile-drawer');\n        drawer.classList.toggle('hidden');\n    }\n\n    const sections = document.querySelectorAll('section[id]');\n    const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n    window.addEventListener('scroll', () => {\n        const scrollTop = window.scrollY;\n        const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n        const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n        document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n        let currentId = 'sec-exec';\n        sections.forEach(sec => {\n            const top = sec.offsetTop - 160;\n            if (scrollTop >= top) {\n                currentId = sec.getAttribute('id');\n            }\n        });\n\n        navLinks.forEach(link => {\n            link.classList.remove('active');\n            const numSpan = link.querySelector('span span');\n            if (numSpan) {\n                numSpan.classList.remove('text-takedared-400');\n                numSpan.classList.add('text-slate-500');\n            }\n            if (link.dataset.target === currentId) {\n                link.classList.add('active');\n                if (numSpan) {\n                    numSpan.classList.remove('text-slate-500');\n                    numSpan.classList.add('text-takedared-400');\n                }\n            }\n        });\n    });\n\n    function filterCompetitors(category) {\n        document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n            if (btn.dataset.filter === category) {\n                btn.classList.add('bg-takedared-500', 'text-white', 'font-semibold', 'shadow-sm');\n                btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n            } else {\n                btn.classList.remove('bg-takedared-500', 'text-white', 'font-semibold', 'shadow-sm');\n                btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n            }\n        });\n\n        const rows = document.querySelectorAll('#comp-table-body tr');\n        rows.forEach(row => {\n            const rowCat = row.dataset.category;\n            if (category === 'all' || rowCat === category) {\n                row.style.display = '';\n            } else {\n                row.style.display = 'none';\n            }\n        });\n    }\n\n    const KPI_STORAGE_KEY = 'tak_research_kpi_state_v1';\n\n    function loadKpiChecklist() {\n        try {\n            const saved = localStorage.getItem(KPI_STORAGE_KEY);\n            if (saved) {\n                const stateMap = JSON.parse(saved);\n                document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n                    if (typeof stateMap[cb.id] === 'boolean') {\n                        cb.checked = stateMap[cb.id];\n                    }\n                });\n            }\n        } catch (e) {}\n        updateKpiChecklist();\n    }\n\n    function updateKpiChecklist() {\n        const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n        const total = checkboxes.length;\n        let checkedCount = 0;\n        const stateMap = {};\n\n        checkboxes.forEach(cb => {\n            stateMap[cb.id] = cb.checked;\n            if (cb.checked) checkedCount++;\n        });\n\n        const pct = Math.round((checkedCount / total) * 100);\n        document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n        try {\n            localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n        } catch (e) {}\n    }\n\n    function resetKpiChecklist() {\n        document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n            cb.checked = false;\n        });\n        updateKpiChecklist();\n    }\n\n    let bizChartInstance = null;\n    let radarChartInstance = null;\n    let compMarginChartInstance = null;\n    let valEvolutionChartInstance = null;\n    let currentBizMode = 'revenue';\n\n    function getChartColors() {\n        const isDark = document.documentElement.classList.contains('dark');\n        return {\n            text: isDark ? '#CBD5E1' : '#475569',\n            grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n            radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n        };\n    }\n\n    function initBizChart() {\n        const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n        const colors = getChartColors();\n\n        const revConfig = {\n            type: 'bar',\n            data: {\n                labels: ['FY23', 'FY24', 'FY25', 'FY26 H1', 'FY26(E)'],\n                datasets: [\n                    {\n                        label: '全年/半期总营收 (¥B)',\n                        data: [4260.0, 4505.7, 4600.0, 2407.0, 4700.0],\n                        backgroundColor: '#D50032',\n                        borderRadius: 4,\n                    },\n                    {\n                        label: '经营利润 Operating Profit (¥B)',\n                        data: [280.0, 310.0, 350.0, 406.7, 453.0],\n                        backgroundColor: '#3B82F6',\n                        borderRadius: 4,\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                    },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => `${ctx.dataset.label}: ¥${ctx.parsed.y}B`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    },\n                    y: {\n                        max: 5200,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => '¥' + v + 'B' }\n                    }\n                }\n            }\n        };\n\n        const areasConfig = {\n            type: 'bar',\n            data: {\n                labels: ['消化系统 (GI)', '罕见病 (Rare Diseases)', '神经科学 (Neuro)', '肿瘤学 (Oncology)', '血浆制品 (Plasma)'],\n                datasets: [\n                    {\n                        label: '核心治疗领域贡献权重 (%)',\n                        data: [32, 28, 15, 12, 13],\n                        backgroundColor: [\n                            '#D50032',\n                            '#06B6D4',\n                            '#3B82F6',\n                            '#6366F1',\n                            '#F59E0B'\n                        ],\n                        borderRadius: 6,\n                        barThickness: 28\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: { display: false },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => `营收贡献占比: ${ctx.parsed.y}%`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    },\n                    y: {\n                        max: 40,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n                    }\n                }\n            }\n        };\n\n        if (bizChartInstance) bizChartInstance.destroy();\n        bizChartInstance = new Chart(ctx, currentBizMode === 'revenue' ? revConfig : areasConfig);\n    }\n\n    function switchBizChart(mode) {\n        currentBizMode = mode;\n        const btnRev = document.getElementById('btn-chart-rev');\n        const btnAre = document.getElementById('btn-chart-are');\n        const titleEl = document.getElementById('biz-chart-title');\n        const subEl = document.getElementById('biz-chart-sub');\n\n        if (mode === 'revenue') {\n            btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-takedared-600 dark:text-takedared-400 shadow-sm transition';\n            btnAre.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n            titleEl.textContent = 'FY2023–FY2027E 核心营业收入与利润演进趋势';\n            subEl.textContent = 'FY26 上半年营收实现 +8.4% 增长，经营利润强劲跃升至 ¥406.7B';\n        } else {\n            btnAre.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-takedared-600 dark:text-takedared-400 shadow-sm transition';\n            btnRev.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n            titleEl.textContent = '五大核心治疗领域营收贡献权重分布';\n            subEl.textContent = '消化系统与罕见病构成双核压舱石，肿瘤与神经专科高速成长';\n        }\n        initBizChart();\n    }\n\n    function initRadarChart() {\n        const ctx = document.getElementById('moatRadarChart').getContext('2d');\n        const colors = getChartColors();\n\n        if (radarChartInstance) radarChartInstance.destroy();\n        radarChartInstance = new Chart(ctx, {\n            type: 'radar',\n            data: {\n                labels: [\n                    '专科与罕见病临床壁垒',\n                    '全球80国准入与商业化网络',\n                    '后期创新管线储备 (8大重磅)',\n                    '严苛成本纪律与转型降本',\n                    '血浆采集与血液制品供应链'\n                ],\n                datasets: [\n                    {\n                        label: '武田制药 Takeda (TAK)',\n                        data: [9.5, 9.6, 9.2, 9.0, 9.5],\n                        borderColor: '#D50032',\n                        backgroundColor: 'rgba(213, 0, 50, 0.22)',\n                        pointBackgroundColor: '#D50032',\n                        borderWidth: 2.5\n                    },\n                    {\n                        label: '跨国综合制药平均水平',\n                        data: [8.5, 8.8, 8.0, 7.5, 7.8],\n                        borderColor: '#3B82F6',\n                        backgroundColor: 'rgba(59, 130, 246, 0.14)',\n                        pointBackgroundColor: '#3B82F6',\n                        borderWidth: 1.8\n                    },\n                    {\n                        label: '仿制药与中小型专科药企',\n                        data: [5.0, 4.5, 5.0, 6.0, 4.0],\n                        borderColor: '#94A3B8',\n                        backgroundColor: 'rgba(148, 163, 184, 0.12)',\n                        pointBackgroundColor: '#94A3B8',\n                        borderWidth: 1.5,\n                        borderDash: [4, 4]\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n                    }\n                },\n                scales: {\n                    r: {\n                        min: 0,\n                        max: 10,\n                        ticks: { display: false, stepSize: 2 },\n                        grid: { color: colors.grid },\n                        angleLines: { color: colors.radarAngle },\n                        pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n                    }\n                }\n            }\n        });\n    }\n\n    function initCompMarginChart() {\n        const ctx = document.getElementById('compMarginChart').getContext('2d');\n        const colors = getChartColors();\n\n        if (compMarginChartInstance) compMarginChartInstance.destroy();\n        compMarginChartInstance = new Chart(ctx, {\n            type: 'bar',\n            data: {\n                labels: [\n                    'AbbVie 艾伯维 (ABBV)',\n                    'Takeda 武田制药 (TAK)',\n                    'CSL Limited (澳大利亚血浆龙头)'\n                ],\n                datasets: [{\n                    label: '毛利率 Gross Margin (%)',\n                    data: [70.0, 64.8, 58.0],\n                    backgroundColor: [\n                        '#3B82F6',\n                        '#D50032',\n                        '#06B6D4'\n                    ],\n                    borderRadius: 6,\n                    barThickness: 26\n                }]\n            },\n            options: {\n                indexAxis: 'y',\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: { display: false },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => `毛利率: ${ctx.parsed.x}%`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        max: 85,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n                    },\n                    y: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    }\n                }\n            }\n        });\n    }\n\n    function initValEvolutionChart() {\n        const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n        const colors = getChartColors();\n\n        if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n        valEvolutionChartInstance = new Chart(ctx, {\n            type: 'bar',\n            data: {\n                labels: ['FY23', 'FY24', 'FY25', 'FY26 H1', 'FY26(E)'],\n                datasets: [\n                    {\n                        type: 'bar',\n                        label: '全年/半期总营收 (¥T)',\n                        data: [4.26, 4.51, 4.60, 2.41, 4.70],\n                        backgroundColor: 'rgba(213, 0, 50, 0.85)',\n                        borderRadius: 5,\n                        barThickness: 26,\n                        yAxisID: 'y'\n                    },\n                    {\n                        type: 'bar',\n                        label: '核心经营利润 Core Operating Profit (¥B)',\n                        data: [1000, 1050, 1100, 710.6, 1190],\n                        backgroundColor: 'rgba(59, 130, 246, 0.85)',\n                        borderRadius: 5,\n                        barThickness: 26,\n                        yAxisID: 'y1'\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                    },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => ctx.dataset.yAxisID === 'y'\n                                ? `${ctx.dataset.label}: ¥${ctx.parsed.y} Trillion`\n                                : `${ctx.dataset.label}: ¥${ctx.parsed.y} Billion`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    },\n                    y: {\n                        type: 'linear',\n                        position: 'left',\n                        max: 5.5,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => '¥' + v + 'T' }\n                    },\n                    y1: {\n                        type: 'linear',\n                        position: 'right',\n                        min: 0,\n                        max: 1400,\n                        grid: { drawOnChartArea: false },\n                        ticks: { color: '#3B82F6', font: { size: 11, weight: '600' }, callback: v => '¥' + v + 'B' }\n                    }\n                }\n            }\n        });\n    }\n\n    function updateChartsTheme() {\n        initBizChart();\n        initRadarChart();\n        initCompMarginChart();\n        initValEvolutionChart();\n    }\n\n    // Calculator Logic\n    const invSlider = document.getElementById('invSlider');\n    const yrSlider = document.getElementById('yrSlider');\n    const grSlider = document.getElementById('grSlider');\n\n    function updateCalculator() {\n        const principal = parseFloat(invSlider.value);\n        const years = parseInt(yrSlider.value);\n        const growthRate = parseFloat(grSlider.value) / 100;\n\n        document.getElementById('invVal').textContent = '$' + principal.toLocaleString();\n        document.getElementById('yrVal').textContent = years + ' 年';\n        document.getElementById('grVal').textContent = (growthRate * 100).toFixed(1) + '%';\n\n        const finalVal = principal * Math.pow(1 + growthRate, years);\n        const totalGain = finalVal - principal;\n        const gainPct = (totalGain / principal) * 100;\n        const impliedPrice = 21.43 * Math.pow(1 + growthRate * 0.85, years);\n\n        document.getElementById('finalBalance').textContent = '$' + Math.round(finalVal).toLocaleString();\n        document.getElementById('totalGainPct').textContent = '累计总回报 +' + gainPct.toFixed(1) + '%';\n        document.getElementById('impliedPrice').textContent = '$' + impliedPrice.toFixed(2);\n        document.getElementById('cagrVal').textContent = (growthRate * 100).toFixed(1) + '%';\n    }\n\n    [invSlider, yrSlider, grSlider].forEach(el => el.addEventListener('input', updateCalculator));\n\n    window.addEventListener('DOMContentLoaded', () => {\n        loadKpiChecklist();\n        initBizChart();\n        initRadarChart();\n        initCompMarginChart();\n        initValEvolutionChart();\n        updateCalculator();\n    });\n    </script>\n</body>\n</html>\n"};
